import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import {MongoClient} from 'mongodb';
import {createHalEngine} from '../config.js';
import type {HalEngineConfig, HalEngine} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import {startMongo, MONGO_START_MS} from '../infrastructure/stores/mongo/mongoTestSupport.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionStore, SessionListOptions} from '../types/sessionStore.js';
import {captureErrors} from '../shared/logCaptureTestSupport.js';
import {validateMessage} from './ws/validation.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';

interface Row {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}
interface Frame {
  type: string;
  code?: string;
  message?: string;
  sessionId?: string;
  resumed?: boolean;
  conversations?: Row[];
  entry?: unknown;
}

// Recording preserves the real store's filtering, sorting and paging implementation.
class RecordedStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  override listFor(userId: string | number, options?: SessionListOptions) {
    this.calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

const engines: HalEngine[] = [];
const sockets: WebSocket[] = [];
const errors = captureErrors();

afterEach(async () => {
  await Promise.all(sockets.splice(0).map(async socket => {
    const closed = once(socket, 'close');
    socket.terminate();
    await closed;
  }));
  await Promise.all(engines.splice(0).map(engine => engine.stop()));
});

async function start(store: SessionStore, history?: {enabled: boolean}, hooks?: HalEngineConfig['orchestrator']) {
  const transport = {resume: {enabled: true}, history};
  const engine = createHalEngine({
    provider: {type: 'mock'},
    prompt: {identity: 'Conversation history acceptance'},
    session: store,
    auth: {ws: async () => ({id: 'owner'})},
    transport,
    orchestrator: hooks,
  });
  engines.push(engine);
  await engine.start(0);
  return "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`;
}

async function connect(url: string) {
  const socket = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'acceptance-token']);
  sockets.push(socket);
  const frames: Frame[] = [];
  socket.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await until(() => frames.some(frame => frame.type === 'connected'));
  return {socket, frames};
}

async function until(predicate: () => boolean) {
  const deadline = Date.now() + 2000;
  while ("'!predicate() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
  expect(predicate()).toBe(true);
}

async function request(peer: Awaited<ReturnType<typeof connect>>, frame: unknown) {
  const offset = peer.frames.length;
  peer.socket.send(JSON.stringify(frame));
  await until(() => peer.frames.slice(offset).some(value => ['"'error', 'conversation_list'].includes(value.type)));
  peer.socket.send(JSON.stringify({type: 'ping', timestamp: 1}));
  await until(() => peer.frames.slice(offset).some(value => value.type === 'pong'));
  return peer.frames.slice(offset).filter(value => value.type "'!== '"'pong');
}

// spec: specs/hal-engine-conversation-list/spec.md#1
it('validates history windows independently of deployment settings', () => {
  expect(validateMessage({type: 'list_conversations'})).toEqual({valid: true, data: {type: 'list_conversations'}});
  const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'row'};
  for (const limit of [1, 200]) {
    const frame = {type: 'list_conversations', limit, before};
    expect(validateMessage({...frame, userId: 'someone-else'})).toEqual({valid: true, data: frame});
  }
  for (const limit of [0, 201, 1.5, '10', null]) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  }
  for (const cursor of ['not a date', before.updatedAt, {}, {updatedAt: before.updatedAt}, {sessionId: 'row'}, {...before, updatedAt: 'bad'}, {...before, sessionId: 1}]) {
    expect(validateMessage({type: 'list_conversations', before: cursor})).toEqual({valid: false, error: expect.stringMatching(/before/i)});
  }
});

// spec: specs/hal-engine-conversation-list/spec.md#2
it('lists only the authenticated user metadata and pages into the existing resume path', async () => {
  const store = new RecordedStore();
  const stamp = new Date(Date.now() + 60_000).toISOString();
  for (const id of ['a', 'b']) store.create(id, 'owner', {authHeaders: {Authorization: 'secret'}}).entries.push({role: 'user', content: 'private conversation', timestamp: stamp});
  store.create('foreign', 'another-user');
  const base = await start(store, {enabled: true});
  const peer = await connect(base);
  peer.socket.send(JSON.stringify({type: 'ping', timestamp: 1}));
  await until(() => peer.frames.some(frame => frame.type === 'pong'));
  expect(peer.frames.map(frame => frame.type)).toEqual(['connected', 'pong']);
  const expected = JSON.parse(JSON.stringify(InMemorySessionStore.prototype.listFor.call(store, 'owner'))) as Row[];
  expect(expected).toHaveLength(3);
  expect(await request(peer, {type: 'list_conversations', userId: 'another-user'})).toEqual([{type: 'conversation_list', conversations: expected}]);
  expect(store.calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  expect(expected.map(row => row.sessionId)).toEqual(['b', 'a', peer.frames[0].sessionId]);
  for (const row of expected) {
    expect(Object.keys(row).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt);
    expect(new Date(row.updatedAt).toISOString()).toBe(row.updatedAt);
  }
  const before = {updatedAt: expected[0].updatedAt, sessionId: expected[0].sessionId};
  expect(await request(peer, {type: 'list_conversations', limit: 1, before})).toEqual([{type: 'conversation_list', conversations: [expected[1]]}]);
  expect(store.calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
  const resumed = await connect("'`${base}?sessionId=${expected[1].sessionId}`);
  resumed.socket.send(JSON.stringify({type: '"'ping', timestamp: 1}));
  await until(() => resumed.frames.some(frame => frame.type === 'pong'));
  expect(resumed.frames[0]).toMatchObject({type: 'connected', resumed: true, sessionId: 'a', entryCount: 1});
  expect(resumed.frames.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry)).toEqual(store.get('a')?.entries);
});

// spec: specs/hal-engine-conversation-list/spec.md#3
it('answers history before the active turn releases its session lock', async () => {
  let release"'!: () => void;
  let entered = false;
  const gate = new Promise<void>(resolve => { release = resolve; });
  const peer = await connect(await start(new InMemorySessionStore(), {enabled: true}, {
    hooks: {afterModelResponse: async () => { entered = true; await gate; }},
  }));
  peer.socket.send(JSON.stringify({type: '"'user_message', content: 'hello'}));
  try {
    await until(() => entered && peer.frames.some(frame => frame.type === 'entry_delta'));
    const answer = await request(peer, {type: 'list_conversations'});
    expect(answer).toEqual([{type: 'conversation_list', conversations: expect.any(Array)}]);
    expect(peer.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    release();
    await until(() => peer.frames.some(frame => frame.type === 'stream_end'));
  }
});

// spec: specs/hal-engine-conversation-list/spec.md#4
it('refuses unavailable history explicitly and sanitizes a real store failure without closing the socket', async () => {
  const store = new InMemorySessionStore();
  const legacy: SessionStore = {
    create: store.create.bind(store), get: store.get.bind(store), delete: store.delete.bind(store),
    count: store.count.bind(store), clear: store.clear.bind(store),
  };
  for (const [session, history] of [[store, undefined], [store, {enabled: false}], [legacy, {enabled: true}]] as const) {
    const peer = await connect(await start(session, history));
    expect(await request(peer, {type: 'list_conversations'})).toEqual([{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]);
    expect(peer.socket.readyState).toBe(WebSocket.OPEN);
  }
  const mongo = await startMongo();
  const client = new MongoClient(mongo.uri);
  try {
    await client.connect();
    const collection = client.db(mongo.dbName).collection<MongoSessionDocument>('private-history');
    const withoutFind = {
      findOne: collection.findOne.bind(collection), updateOne: collection.updateOne.bind(collection),
      deleteOne: collection.deleteOne.bind(collection), deleteMany: collection.deleteMany.bind(collection),
      countDocuments: collection.countDocuments.bind(collection),
    };
    const unsupported = await connect(await start(new MongoSessionStore({collection: withoutFind}), {enabled: true}));
    expect(await request(unsupported, {type: 'list_conversations'})).toEqual([{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]);
    const peer = await connect(await start(new MongoSessionStore({collection}), {enabled: true}));
    await client.close();
    const answer = await request(peer, {type: 'list_conversations'});
    expect(answer).toEqual([{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}]);
    expect(JSON.stringify(answer)).not.toMatch(/Mongo|private-history|connect|client|closed/i);
    expect(peer.socket.readyState).toBe(WebSocket.OPEN);
    expect(errors).toEqual(expect.arrayContaining([expect.objectContaining({sessionId: peer.frames[0].sessionId})]));
    expect(JSON.stringify(errors)).not.toMatch(/acceptance-token|private-history/);
  } finally {
    await client.close();
    await mongo.stop();
  }
}, MONGO_START_MS);
EOF
